    'Cun ERTE, a indemnización debería calcularse co salario completo de antes do ERTE, non co das túas últimas nóminas (STS 678/2018 e STS 638/2022). Sen ese salario non se dá unha cifra.',
  'client.calculation.severance.first_stretch':
    'Tramo ata o 11-02-2012: {meses} meses × 3,75 = {dias} días.',
  'client.calculation.severance.second_stretch':
    'Tramo desde o 12-02-2012: {meses} meses × 2,75 = {dias} días.',
  'client.calculation.severance.over_cap':
    'Supera {tope} días: o tramo posterior non suma e o máximo é {maximo} días.',
  'client.calculation.severance.cap': 'Límite de {tope} días.',
  'client.calculation.severance.total': 'Total {dias} días × {diario}/día.',
  'client.calculation.severance.cgpj_range':
    'A calculadora do CGPJ e a súa guía contan distinto os meses neste caso (un mes de diferenza); por iso damos unha marxe entre ambas cifras.',
  'client.calculation.severance.fixed_term': '{dias} días × {dias_anuales}/365 × {diario}/día',
  'client.calculation.severance.fixed_term_before_2001':
    'Os contratos temporais asinados antes do 4 de marzo de 2001 non teñen esta indemnización: réxense pola norma de entón (DT 8.ª ET), agás que o convenio a prevexa.',
  'client.calculation.severance.replacement':
    'Os contratos de substitución non xeran indemnización por fin de contrato.',
  'client.calculation.severance.training':
    'Os contratos de formación non xeran indemnización por fin de contrato.',
  'client.calculation.severance.resignation': 'A dimisión voluntaria non xera indemnización.',
  'client.calculation.severance.disciplinary':
    'O despedimento disciplinario declarado procedente non xera indemnización. Se se declara improcedente, calcúlase como un despedimento improcedente.',
  'client.calculation.late_interest':
    '10 % ao ano × {base} × {dias} días desde a baixa / 365 = {importe}. O Tribunal Supremo aplícao ás débedas de salario aínda que a cantidade se discuta (STS de 17 de xuño de 2014, rcud 1315/2013).',
  'client.calculation.late_interest.scope':
    'Só conta o que é salario: o salario do mes da baixa e as pagas extraordinarias, polo seu mínimo legal. A indemnización non leva este xuro, e as vacacións non gozadas non se suman porque é dubidoso que o leven.',
  'client.warning.cause_unknown.title': 'Sen a causa',
  'client.warning.cause_unknown':
    'Sen a causa só se revisan as partidas que non dependen dela: o salario do mes da baixa, as vacacións e as pagas extraordinarias. A indemnización non se calcula. A causa está na carta de despedimento e no certificado de empresa, no recadro «causa de la situación legal de desempleo».',
  'client.warning.null_dismissal.title': 'Este despedimento podería ser nulo',
  'client.warning.null_dismissal.protected':
    'Polo que marcaches, o despedimento podería ser nulo (art. 55.5 ET), agás que o motivo non teña nada que ver con esa situación.',
  'client.warning.null_dismissal.sick_leave':
    'Despedir alguén de baixa médica podería ser nulo se o motivo é a enfermidade: a Ley 15/2022 prohibe discriminar por enfermidade ou condición de saúde e fai nulos eses actos (arts. 2.1 e 26). Os tribunais aínda non o aplican de forma uniforme.',
  'client.warning.null_dismissal.effects':
    'Se un xulgado o declarase nulo, a empresa tería que readmitirte e pagarche os salarios que deixaches de cobrar (arts. 55.6 e 53.5 ET). Esta revisión non calcula cifras para ese caso.',
  'client.warning.null_dismissal.deadline':
    'Para impugnar o despedimento hai 20 días hábiles desde a data de baixa (art. 59.3 ET); presentar a papeleta de conciliación interrompe o prazo. Un despacho laboralista, unha asesoría laboral ou un sindicato poden dicirche como se aplica ao teu caso.',
  'client.warning.erte_unknown.title': 'Se estabas nun ERTE',
  'client.warning.erte_unknown':
    'Cun ERTE, a indemnización debería calcularse co salario completo de antes do ERTE: con xornada reducida, o de antes da redución (STS 678/2018); co contrato suspendido, o cobrado nos meses traballados (STS 638/2022). Se algunha das túas últimas nóminas é dun ERTE, a indemnización desta revisión pode quedar curta.',
  'client.warning.late_interest.title': 'Se aínda non che pagaron',
  'client.warning.late_interest.amount':
    'O que é salario leva un xuro polo atraso do 10 % ao ano (art. 29.3 ET): uns {importe} desde a baixa ata hoxe. A indemnización non o leva, e as vacacións non gozadas non se suman porque é dubidoso que o leven.',
  'client.warning.late_interest.none':
    'O que é salario leva un xuro polo atraso do 10 % ao ano (art. 29.3 ET), contado desde a baixa; hoxe aínda non suma nada. A indemnización non o leva, e as vacacións non gozadas non se suman porque é dubidoso que o leven.',
  'client.warning.late_interest.days_left':
    'Para reclamar as cantidades do finiquito hai un ano desde a baixa (art. 59.1 e 59.2 ET): quédanche {dias} días para reclamalo.',
  'client.warning.late_interest.one_day_left':
    'Para reclamar as cantidades do finiquito hai un ano desde a baixa (art. 59.1 e 59.2 ET): quédache 1 día para reclamalo.',
  'client.warning.late_interest.last_day':
    'Para reclamar as cantidades do finiquito hai un ano desde a baixa (art. 59.1 e 59.2 ET): hoxe é o último día.',
  'client.warning.late_interest.lapsed':
    'Pasou máis dun ano desde a baixa, así que pode ter prescrito (art. 59.1 e 59.2 ET), agás que algo interrompese o prazo. Por iso non se conta o xuro.',
  'client.warning.late_interest.other_deadline':
    'É un prazo distinto dos 20 días hábiles para impugnar un despedimento (art. 59.3 ET).',
