  'bills.crumb': 'Facturas',
  'bills.title': 'Factura da luz e permanencia do móbil ou internet',
  'bills.description':
    'A túa factura da luz liña por liña fronte aos teus prezos e á norma, e a penalización e a baixa do teu contrato de móbil ou internet.',
  'bills.h1': 'As túas facturas, fronte á norma',
  'bills.lead':
    'Dúas revisións: a túa factura da luz, liña por liña, e a penalización e a baixa do teu contrato de móbil ou internet.',
  'bills.note': 'O que escribes non sae do teu dispositivo.',
  'bills.hub.label': 'Facturas',
  'bills.hub.electricity': 'Luz',
  'bills.hub.electricity_situation':
    'Chégache a factura da luz: cada liña fronte aos teus prezos e á norma',
