    'A prima dun seguro entra na TAE cando o seguro é obrigatorio para obter o crédito.',
  'client.credit.calculation.information.linked_insurance.withdrawal':
    'Se desistes do crédito, o seguro accesorio queda sen efecto (art. 28.3).',
  'client.credit.calculation.information.linked_insurance.unused_premium':
    'Se o devolves antes, o art. 30.6 ocúpase da parte da prima que non se consumiu.',
  'client.credit.calculation.information.unused_premium.guide':
    'Como orientación, repartindo a prima a partes iguais polos días do préstamo, a parte sen consumir sería duns {euros}. É orientativa: a túa póliza fixa o método.',
  'client.credit.calculation.information.cash_price':
    'Nunha compra financiada, o contrato ten que dicir o ben e o seu prezo ao contado (art. 16.2).',
  'client.credit.calculation.information.linked_credit':
    'Se o préstamo serve só para pagar a compra dun ben ou dun servizo concretos e forma unha unidade con esa compra, é un crédito vinculado (art. 29.1). Entón o contrato ten que dicir o ben e o seu prezo ao contado (art. 16.2.e); se desistes da compra, o préstamo deixa de obrigarte sen penalización (art. 29.2); e se o ben non chega ou non é conforme, nalgúns casos eses dereitos valen tamén fronte ao prestamista (art. 29.3).',
  'client.credit.calculation.information.cash_option':
    'E podes non financiar a compra e pagala como acordaches co vendedor (art. 26.3).',
  'client.credit.calculation.information.revolving_info':
    'A orde de transparencia bancaria prevé que unha tarxeta revolving informe polo menos cada trimestre do que se debe, o tipo, a cota e cando e por canto acabarías de pagala (art. 33 quinquies), e que, se o pides, che dean en 5 días hábiles o pagado e o que se debe, coas partes detalladas, e un cadro de amortización (art. 33 sexies). Non se comprobou a que entidades e contratos anteriores chega, así que non se afirma que a túa o deba.',
  'client.credit.calculation.information.card_payoff.months':
    'Cunha débeda de {balance} e pagando {payment} ao mes sen novas compras, tardarías {months} en pagala e pagarías {interest} de xuros.',
