  'client.credit.letter.information.schedule':
    'O art. 16.2.i da Ley 16/2011, de contratos de crédito al consumo, recolle o dereito a recibir, se se pide, de forma gratuíta e en calquera momento do contrato, un extracto en forma de cadro de amortización. Pídolle o cadro de amortización do meu crédito.',
