  'client.credit.letter.repayment.up_to_a_year':
    'Entre ese día e o final pactado quedaba un ano ou menos, contado de data a data, así que a lei fixa como límite o 0,5 % do importe reembolsado (art. 30.2 da Ley 16/2011, de contratos de crédito al consumo).',
